\title[Landauer's Principle from First Principles]{Landauer's Principle from First
Principles: Relative Entropy, the Jarzynski Second Law, and the Saturation Condition}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}

\begin{abstract}
We give a fully elementary, self-contained derivation of Landauer's principle for the
erasure of a finite memory, organized around three pillars. First, we recast the
Landauer free-energy cost $kT\ln 2$ as a Kullback--Leibler (relative) entropy,
$kT\,\KL{\text{erased}}{\text{uniform}}$, and prove Gibbs' inequality
$\KL{p}{q}\ge 0$ from the single elementary bound $\ln x \le x-1$; this furnishes a
distribution-comparison account of the erasure cost dual to the usual Shannon-entropy
account, and the two are shown to coincide exactly. Second, we upgrade the exact finite
Jarzynski work identity to the second-law inequality $\Delta F \le \E[W]$ using only the
convexity bound $1+x\le e^{x}$, recovering Landauer's principle $kT\ln 2 \le \E[W]$ as a
genuine lower bound, and we show that logical irreversibility (non-injectivity of the
erasure map) forces strictly positive dissipation. Third, we determine the saturation
condition: the bound is attained iff the dissipated work has no fluctuations on the
support of the distribution (the quasi-static, reversible limit), via the strict
convexity bound $1+x<e^{x}$ for $x\neq 0$. We complement these with the extensivity of
the bound for $n$-bit registers ($n\,kT\ln 2$) and the deterministic data-processing
inequality $H(f_*p)\le H(p)$, which exhibits reversible computation as the
zero-dissipation boundary case. All results have been formalized and machine-checked.
\end{abstract}

\maketitle

\section{Introduction}

Landauer's principle \cite{Landauer1961} asserts that the erasure of one bit of
information in an environment at absolute temperature $T$ requires the dissipation of at
least $kT\ln 2$ of energy, where $k$ is Boltzmann's constant. It is the cleanest known
bridge between \emph{information} and \emph{thermodynamics}. Our aim is to isolate the
\emph{minimal} mathematical content of each physical claim. We work over a finite
probability space throughout, so that all sums are finite and every step is elementary.

The contributions are: (1) a relative-entropy formulation of the erasure cost with a
one-line proof of Gibbs' inequality (\S\ref{sec:rel}); (2) a derivation of the
second-law inequality and Landauer's lower bound from $1+x\le e^x$ alone
(\S\ref{sec:second}); (3) a saturation theorem identifying tightness with reversibility
via $1+x<e^x$ (\S\ref{sec:sat}); and (4) extensivity for $n$-bit registers together with
the data-processing inequality identifying reversible computation as the unique
zero-dissipation case (\S\ref{sec:ext}).

\section{Setup and definitions}\label{sec:setup}

Let $\Omega$ be a finite set. A \emph{weight function} is any $p:\Omega\to\R$.

\begin{definition}[Expectation]
For weight $p$ and observable $f:\Omega\to\R$, $\E_p[f]=\sum_{\omega\in\Omega}p(\omega)f(\omega)$.
\end{definition}

\begin{definition}[PMF]
$p$ is a \emph{probability mass function} if $p(\omega)\ge 0$ for all $\omega$ and
$\sum_\omega p(\omega)=1$.
\end{definition}

\begin{definition}[Shannon entropy]
With the convention $0\ln 0=0$ (encoded by $\negMulLog(x)=-x\ln x$),
$H(p)=\sum_\omega \negMulLog(p(\omega))=-\sum_\omega p(\omega)\ln p(\omega)$.
\end{definition}

\begin{definition}[One-bit distributions]
On $\Omega=\mathrm{Bool}$: the uniform bit $u(b)=\tfrac12$; the fully erased bit
$e(b)=\mathbf 1[b=\mathrm{false}]$; and the erasure map $\mathrm{er}(b)=\mathrm{false}$.
\end{definition}

\begin{definition}[Jarzynski condition]
A work observable $W:\Omega\to\R$ satisfies the finite Jarzynski equality at inverse
temperature $\alpha$ with free-energy difference $\Delta F$ if
$\E_p[e^{-\alpha W}]=e^{-\alpha\Delta F}$.
\end{definition}

\begin{lemma}\label{lem:entloss}
$H(u)=\ln 2$, $H(e)=0$, and hence $H(u)-H(e)=\ln 2$.
\end{lemma}
\begin{proof}[Sketch]
$H(u)=-2\cdot\tfrac12\ln\tfrac12=\ln 2$; the erased bit has a single certain outcome,
so $H(e)=0$; subtract.
\end{proof}

\begin{lemma}\label{lem:noninj}
The erasure map $\mathrm{er}:\mathrm{Bool}\to\mathrm{Bool}$ is not injective.
\end{lemma}
\begin{proof}[Sketch]
It sends both $\mathrm{true}$ and $\mathrm{false}$ to $\mathrm{false}$.
\end{proof}

\section{Landauer's cost as a relative entropy}\label{sec:rel}

\begin{definition}[Relative entropy / KL divergence]
For weights $p,q:\Omega\to\R$,
\[ \KL{p}{q}=\sum_\omega p(\omega)\,\ln\frac{p(\omega)}{q(\omega)}. \]
The leading factor $p(\omega)$ makes $0\cdot\ln 0=0$ automatic.
\end{definition}

\begin{theorem}[Self-divergence]\label{thm:self}
$\KL{p}{p}=0$ for every $p$.
\end{theorem}
\begin{proof}[Sketch]
Termwise: either $p(\omega)=0$ (the factor kills the term) or $\ln 1=0$.
\end{proof}

\begin{theorem}[Gibbs' inequality]\label{thm:gibbs}
Let $p,q$ be PMFs with $q(\omega)>0$ for all $\omega$. Then $\KL{p}{q}\ge 0$.
\end{theorem}
\begin{proof}[Sketch]
Use the tangent bound $\ln x\le x-1$ ($x>0$). We claim the pointwise bound
$p(\omega)\ln\frac{p(\omega)}{q(\omega)}\ge p(\omega)-q(\omega)$. If $p(\omega)=0$ this
reads $0\ge -q(\omega)$, true. If $p(\omega)>0$, apply $\ln x\le x-1$ to
$x=q(\omega)/p(\omega)>0$ and multiply by $p(\omega)$. Summing and using
$\sum_\omega p(\omega)=\sum_\omega q(\omega)=1$,
\[ \KL{p}{q}\ge\sum_\omega\big(p(\omega)-q(\omega)\big)=1-1=0. \qedhere \]
\end{proof}

\begin{theorem}[Erased-vs-uniform divergence]\label{thm:erunif}
$\KL{e}{u}=\ln 2$.
\end{theorem}
\begin{proof}[Sketch]
The $\mathrm{false}$ term contributes $1\cdot\ln(1/\tfrac12)=\ln 2$; the $\mathrm{true}$
term contributes $0$.
\end{proof}

\begin{theorem}[Bridge identity]\label{thm:bridge}
$\KL{e}{u}=H(u)-H(e)$.
\end{theorem}
\begin{proof}[Sketch]
Both sides equal $\ln 2$ by Theorems~\ref{thm:erunif} and Lemma~\ref{lem:entloss}. The
content is that an asymmetric divergence and a difference of single-distribution
entropies agree exactly against the uniform reference.
\end{proof}

\begin{theorem}[Landauer cost as relative entropy]\label{thm:costkl}
For all $k,T\in\R$, $\;kT\ln 2 = kT\,\KL{e}{u}$.
\end{theorem}

\begin{theorem}[Nonnegativity of relative-entropy work]\label{thm:worknn}
Let $p,q$ be PMFs with $q>0$ pointwise and $k,T\ge 0$. Then $0\le kT\,\KL{p}{q}$.
\end{theorem}
\begin{proof}[Sketch]
Gibbs (Theorem~\ref{thm:gibbs}) gives $\KL{p}{q}\ge 0$; multiply by $kT\ge 0$.
\end{proof}

The quantity $kT\,\KL{p}{q}$ is the nonequilibrium excess free energy of state $p$
relative to equilibrium $q$ \cite{EspositoVdB2011}; Theorem~\ref{thm:worknn} is the
information-theoretic second law, and Theorem~\ref{thm:costkl} specializes it to one-bit
erasure.

\section{The Jarzynski second law and Landauer's lower bound}\label{sec:second}

\begin{theorem}[Jarzynski correction]\label{thm:jcorr}
If $\alpha\neq 0$ and $W$ satisfies the Jarzynski condition with free-energy difference
$\Delta F$, then
\[ \E_p[W]=\Delta F+\alpha^{-1}\ln\E_p\!\Big[e^{-\alpha(W-\E_p[W])}\Big]. \]
\end{theorem}
\begin{proof}[Sketch]
Factor $e^{-\alpha(W-\langle W\rangle)}=e^{\alpha\langle W\rangle}e^{-\alpha W}$, pull
out the constant, apply the Jarzynski identity, take the logarithm, and rearrange.
\end{proof}

\begin{theorem}[Finite Jensen bound]\label{thm:jensen}
For any PMF $p$ and observable $g$, $\;1+\E_p[g]\le\E_p[e^{g}]$.
\end{theorem}
\begin{proof}[Sketch]
$1+g(\omega)\le e^{g(\omega)}$ pointwise; multiply by $p(\omega)\ge 0$ and sum, using
$\sum_\omega p(\omega)=1$.
\end{proof}

\begin{lemma}[Centred work has zero mean]\label{lem:cent}
$\E_p[-\alpha(W-\E_p[W])]=0$.
\end{lemma}

\begin{theorem}[Fluctuation factor and correction]\label{thm:fluc}
$\E_p[e^{-\alpha(W-\E_p[W])}]\ge 1$, hence $\ln\E_p[e^{-\alpha(W-\E_p[W])}]\ge 0$.
\end{theorem}
\begin{proof}[Sketch]
Apply Theorem~\ref{thm:jensen} with $g=-\alpha(W-\E_p[W])$ and Lemma~\ref{lem:cent}
($\E_p[g]=0$); monotonicity of $\ln$ and $\ln 1=0$ give the second statement.
\end{proof}

\begin{theorem}[Second law]\label{thm:second}
Let $p$ be a PMF, $\alpha>0$, and $W$ satisfy the Jarzynski condition with $\Delta F$.
Then $\Delta F\le\E_p[W]$.
\end{theorem}
\begin{proof}[Sketch]
Substitute Theorem~\ref{thm:jcorr}; the correction is $\alpha^{-1}>0$ times a
nonnegative logarithm (Theorem~\ref{thm:fluc}).
\end{proof}

\begin{theorem}[Landauer's principle]\label{thm:landauer}
Let $p$ be a PMF and $k,T>0$. If $W$ satisfies the Jarzynski condition at
$\alpha=(kT)^{-1}$ with $\Delta F=kT\ln 2$, then $kT\ln 2\le\E_p[W]$.
\end{theorem}

\begin{theorem}[Cost equals entropy loss]\label{thm:costloss}
For all $k,T$, $\;kT\ln 2=kT\big(H(u)-H(e)\big)$.
\end{theorem}

\begin{theorem}[Logical implies thermodynamic irreversibility]\label{thm:logphys}
Under the hypotheses of Theorem~\ref{thm:landauer},
$\neg\,\Injective(\mathrm{er})$ and $0<\E_p[W]$.
\end{theorem}
\begin{proof}[Sketch]
Non-injectivity is Lemma~\ref{lem:noninj}. Theorem~\ref{thm:landauer} gives
$\E_p[W]\ge kT\ln 2>0$ since $k,T>0$ and $\ln 2>0$.
\end{proof}

\section{The saturation condition: tightness $\Leftrightarrow$ reversibility}\label{sec:sat}

\begin{theorem}[Strict finite Jensen bound]\label{thm:strict}
Let $p$ be a PMF and $g$ an observable that is nonzero somewhere on the support of $p$.
Then $1+\E_p[g]<\E_p[e^{g}]$.
\end{theorem}
\begin{proof}[Sketch]
The strict bound $x+1<e^x$ ($x\neq 0$) holds at any support point with $g(\omega)\neq0$
and the non-strict bound elsewhere; the strict gap, carried by a point of positive
probability, survives summation.
\end{proof}

\begin{theorem}[Saturation $\Leftrightarrow$ zero fluctuations]\label{thm:satzero}
For $\alpha>0$, the Jarzynski correction $\ln\E_p[e^{-\alpha(W-\E_p[W])}]$ vanishes ---
equivalently $\Delta F\le\E_p[W]$ holds with equality --- iff $W$ has no fluctuations on
the support of $p$, i.e. $W=\E_p[W]$ almost surely.
\end{theorem}
\begin{proof}[Sketch]
($\Leftarrow$) Constant $W$ on the support makes the centred work $0$, the exponential
average $1$, and the logarithm $0$. ($\Rightarrow$) If $W$ fluctuates then
$g=-\alpha(W-\E_p[W])$ is nonzero at a support point (here $\alpha>0$ is used), so
Theorem~\ref{thm:strict} gives $1<\E_p[e^g]$ and the correction is strictly positive.
\end{proof}

Physically, Landauer's bound is attained only in the quasi-static, reversible limit;
any genuine fluctuation forces strictly larger mean dissipation. The correction
$\alpha^{-1}\ln\E_p[e^{-\alpha(W-\langle W\rangle)}]$ is the surcharge: nonnegative
always, strictly positive precisely away from reversibility.

\section{Extensivity and the data-processing inequality}\label{sec:ext}

\begin{theorem}[Entropy of the uniform distribution]\label{thm:unifN}
If $|\Omega|=N>0$, the uniform distribution $p(\omega)=1/N$ has $H(p)=\ln N$.
\end{theorem}

\begin{theorem}[Maximal register entropy]\label{thm:regent}
The uniform distribution over $2^n$ states (e.g.\ over $\mathrm{Fin}\,n\to\mathrm{Bool}$)
has entropy $n\ln 2$.
\end{theorem}

\begin{theorem}[Extensive Landauer bound]\label{thm:nbit}
Let $p$ be a PMF, $k,T>0$. If $W$ satisfies the Jarzynski condition at
$\alpha=(kT)^{-1}$ with $\Delta F=n(kT\ln 2)$, then $n\,kT\ln 2\le\E_p[W]$.
\end{theorem}

\begin{theorem}[Per-bit cost]\label{thm:perbit}
For $n>0$, $\;\big(n\,kT\ln 2\big)/n=kT\ln 2$: the guaranteed per-bit cost equals the
single-bit value for every register size.
\end{theorem}

\begin{definition}[Pushforward]
For $f:\alpha\to\beta$ and weight $p:\alpha\to\R$, $f_*p(y)=\sum_{x:\,f(x)=y}p(x)$.
\end{definition}

\begin{theorem}[Deterministic data-processing inequality]\label{thm:dpi}
For any $f$ and nonnegative weights $p$, $\;H(f_*p)\le H(p)$.
\end{theorem}
\begin{proof}[Sketch]
Reindex $H(f_*p)=-\sum_x p(x)\ln f_*p(f(x))$ fiberwise. Since $x$ lies in its own fiber
and weights are nonnegative, $f_*p(f(x))\ge p(x)$; monotonicity of $\ln$ makes each term
of $H(p)-H(f_*p)=\sum_x p(x)\big(\ln f_*p(f(x))-\ln p(x)\big)$ nonnegative.
\end{proof}

\begin{theorem}[Reversible implies entropy-preserving]\label{thm:inj}
If $f$ is injective then $H(f_*p)=H(p)$.
\end{theorem}

\begin{corollary}[Landauer lower bound and reversible freedom]\label{cor:llb}
For $k,T\ge 0$, $\;0\le kT\big(H(p)-H(f_*p)\big)$, with equality whenever $f$ is
injective.
\end{corollary}

Erasure is the extremal collapse $f\equiv\text{const}$, maximizing the entropy drop;
reversible (injective) computation is the boundary case of zero cost.

\section{Discussion}

The entire chain rests on two elementary analytic facts and their strict counterparts:
Gibbs' inequality is the tangent line $\ln x\le x-1$; the second law is $1+x\le e^x$;
saturation is its strictness $1+x<e^x$ for $x\neq 0$; and logical-implies-thermodynamic
irreversibility is the non-injectivity of a two-element map with $kT\ln 2>0$. A
structural highlight is the duality of Theorem~\ref{thm:bridge}: the Shannon entropy
loss $H(u)-H(e)$ and the relative entropy $\KL{e}{u}$ are \emph{a priori} different
functionals that coincide against the uniform reference.

\section*{Future directions}

\noindent\textbf{Conjecture 1 (Monotone fluctuation surcharge).} For mean-zero
fluctuation $X=-(W-\E[W])$, the correction $K(\alpha)=\ln\E[e^{\alpha X}]$ is
nondecreasing on $\alpha\ge0$ with $K(0)=K'(0)=0$: colder operation never decreases the
surcharge above the reversible bound. $K$ is the cumulant generating function of a
mean-zero variable, hence convex with a stationary minimum at the origin; this cycle's
$K(\alpha)\ge0$ (equality iff $X=0$ a.s.) is the minimum statement, and monotonicity is
its derivative-level refinement.

\smallskip
\noindent\textbf{Conjecture 2 (Strict extensivity defect).} The extensive bound
$n\,kT\ln 2$ is saturated iff the bits are independent and each erased reversibly; any
correlation lowers the required entropy production below $n\ln2$ by exactly the total
correlation $\sum_i H(\text{bit}_i)-H(\text{register})$, a relative entropy
$\KL{\text{joint}}{\text{product of marginals}}$ shown nonnegative this cycle.

\smallskip
\noindent\textbf{Conjecture 3 (Pinsker-type quantitative bound).} The surcharge is
bounded below by the squared total-variation distance from the reversible limit,
$\E[W]-\Delta F\ge (kT)\,c\,\|p-p_{\mathrm{rev}}\|_{\mathrm{TV}}^2$ for an absolute
$c>0$; Pinsker's inequality converts the relative-entropy surcharge into a metric lower
bound.

