function KL_LANDAUER(p, q, k, T):
    D <- 0
    for each outcome w:
        if p[w] > 0:
            if q[w] <= 0: return +infinity   # divergence is infinite
            D <- D + p[w] * ln(p[w] / q[w])   # 0*ln0 handled by guard
    return k * T * D                          # Landauer free-energy cost

